mapper.update:
UPDATE config
SET label = #{label}, key = #{key}, value = #{value}, description = #{description},
    is_active = #{isActive}, data_version = data_version + 1, updated_at = #{updatedAt}
WHERE id = #{id} AND data_version = #{dataVersion}

mapper.select:
SELECT  FROM config


        AND (label ILIKE CONCAT('%', #{query}, '%') OR key ILIKE CONCAT('%', #{query}, '%')
             OR value ILIKE CONCAT('%', #{query}, '%') OR description ILIKE CONCAT('%', #{query}, '%'))

    AND label = #{label}
    AND is_active = #{active}

ORDER BY label, key
LIMIT #{limit} OFFSET #{offset}
